let timingListPage=0,timingDetail=null,timingLapPage=0;
let originalHistoryState=null;
async function openOriginalHistory(id,originId=null,offset=0){
 const context=historyContext(),state={carId:id,originId,offset,context};originalHistoryState=state;
 modal('Original Timing history','<p id="original-history-loading" role="status">Loading preserved history…</p>',null);
 const result=await api('historyView',{...historyIdentity(),operation:originId?'original':'originals',carId:id,...(originId?{originId}:{}),offset});
 if(originalHistoryState!==state||historyContext()!==context||!$('#dialog').open||!$('#original-history-loading'))return;
 state.result=result;
 const nav=`<div class="actions mt">${offset?btn('Previous','original-history-prev'):''}${result.nextOffset!==null?btn('Next','original-history-next'):''}${originId?btn('Back to sessions','original-history-list','',id):''}</div>`;
 const status=o=>o.state==='withdrawn'?`<p class="note">Withdrawn · original evidence retained. ${esc(o.changeReason||'')}</p>`:'';
 const content=originId?`<h3>${esc(result.origin.name)}</h3>${status(result.origin)}<p class="note">${esc(result.origin.reason)} These original values are preserved without inventing missing configuration, validity or record eligibility.</p>${historyTable(['Lap','Lane','Driver','Recorded time (ms)','Validity','Pit'],result.laps.map(l=>[l.number,l.lane,l.driver,l.time,l.valid===null?'Unknown':l.valid?'Valid':'Invalid',l.pit===null?'Unknown':l.pit?'Yes':'No']))}`:result.rows.map(o=>panel(o.name,`${status(o)}<p class="muted">${esc(o.reason)}</p><p>${o.lapCount} original lap(s)</p>${btn('View original laps','original-history-open','',o.id)}`)).join('');
 modal('Original Timing history',content+nav,null);
}
async function changeOriginalHistory(delta){const s=originalHistoryState;if(!s||historyContext()!==s.context)return;await openOriginalHistory(s.carId,s.originId,delta>0?s.result.nextOffset:Math.max(0,s.offset-(s.originId?100:20)));}
const timingCount=(n,label)=>n+' '+label+(n===1?'':'s');
const timingKey=r=>r.payload.source.id+':'+r.payload.sessionId;
const timingSeconds=value=>value===null?'—':(value/1000).toLocaleString('en-GB',{minimumFractionDigits:3,maximumFractionDigits:3})+' s';
function timingStatistics(s){return dl([['Valid measured laps',String(s.validLaps)],['Record-eligible laps',String(s.recordEligibleLaps)],['Best eligible lap',timingSeconds(s.bestLapMs)],['Average valid lap',timingSeconds(s.averageLapMs)],['Measured lap time',timingSeconds(s.measuredTimeMs)],['Physical distance',s.distanceM.toLocaleString('en-GB',{maximumFractionDigits:3})+' m'+(s.distanceComplete?'':' (known distance only)')]]);}
function renderTimingResults(car){
  if(typeof renderSharedHistory==='function'&&local()&&db._view?.token&&window.slotforge.historyView)return renderSharedHistory(car)+(db._view.originalHistoryCount?panel('Original Timing history',`<p>${db._view.originalHistoryCount} preserved session(s) include evidence which cannot be represented completely in the measured statistics above. Their original laps remain available.</p>${btn('Browse original sessions','original-history-list','',car.id)}`):'');
  const records=(db.timing?.sessions||[]).filter(r=>r.carIds.includes(car.id)).sort((a,b)=>b.receivedAt.localeCompare(a.receivedAt));
  const count=db._view?.timing?.total??records.length,total=db._view?.timing?.aggregate||TimingResultsModel.aggregate(records,car.id);timingListPage=Math.min(timingListPage,Math.max(0,Math.ceil(count/10)-1));
  return `<section class="timing-results"><div class="page-head"><div><h2>SlotForge Timing sessions</h2><p class="muted">Reviewed results received from Timing, with the configuration captured before racing.</p></div>${badge(timingCount(count,'session'))}</div><p class="tiny muted">${timingCount(total.sessions,'contributing session')} · ${timingCount(total.validLaps,'valid lap')} · ${total.distanceM.toLocaleString('en-GB',{maximumFractionDigits:2})} m${total.distanceComplete?'':' known distance (some distances missing)'} · ${timingCount(total.wins,'classified win')}. Manual records remain separate.</p>${records.length?(db._view?.timing?records:records.slice(timingListPage*10,timingListPage*10+10)).map(r=>{
    if(r.format==='history-v1')return panel(r.lastName,`${badge('Shared racing history','info')}${badge(r.payload.state==='withdrawn'?'Withdrawn':'Stored')}<p class="note mt">This expanded history is preserved in the library and available through shared-history reads. Detailed display is awaiting the coordinated client update. It is excluded from the legacy totals and comparisons shown here.</p>`);
    const s=r.payload,p=s.state==='active'?s.participants.find(p=>p.carId===car.id):null,needsCorrection=r._query?.requiresCorrection??TimingResultsModel.requiresCorrection(s),status=s.state==='withdrawn'?'Withdrawn':!p?'Removed by correction':needsCorrection?'Needs correction':r.history.length?'Corrected':'Received';
    return panel(r.lastName,`<div class="actions">${badge('SlotForge Timing','info')}${badge(status,s.state==='active'&&p&&!needsCorrection?'good':'')}<span class="tiny muted">Revision ${s.revision} · ${esc(s.source.name)}</span></div>${needsCorrection?timingCorrectionNotice():''}${p?`<p class="mt">${esc(s.track.name)} · ${date(s.startedAt)} · ${esc(s.type)}</p><p class="muted">${p.drivers.map(d=>esc(d.name)).join(', ')}</p>${timingStatistics(r._query?.summaries.find(x=>x.participantId===p.id)?.statistics||TimingResultsModel.statistics(s,p))}<p class="tiny muted">Captured configuration ${esc(p.configuration.revision.slice(0,12))} · ${esc(connectionTime(p.configuration.capturedAt))}</p>`:`<p class="note mt">${esc(s.state==='withdrawn'?s.reason:'This car was removed from the corrected session.')} This session contributes no statistics for this car.</p>`}${btn('Session details','timing-session','small',timingKey(r))}`);
  }).join(''):`<div class="panel"><p class="muted">No Timing sessions received for this car. In Connections, enable Dealership Mode and connect Timing with its address and shared password.</p></div>`}${count>10?`<div class="actions mt">${timingListPage?btn('Previous sessions','timing-list-prev'):''}<span>Page ${timingListPage+1} of ${Math.ceil(count/10)}</span>${(timingListPage+1)*10<count?btn('Next sessions','timing-list-next'):''}</div>`:''}</section>`;
}
function timingCorrectionNotice(){return '<p class="note mt">This earlier import contains overlapping measured laps. Its original results are preserved for review, but it contributes no statistics. Correct or withdraw the session in Timing and send a higher revision.</p>';}
async function openTimingSession(key){
 if(local()&&db._view?.token&&window.slotforge.historyView){const [sourceId,sessionId]=key.split(':');return openSharedHistory(sourceId,sessionId,carId);}
 if(db._view?.timing){const [sourceId,sessionId]=key.split(':'),id=carId,context=db.id;const result=await api('query','session',{sourceId,sessionId,carId:id,offset:0,token:db._view.token});if(context!==db.id||id!==carId)return;timingDetail={record:result.record,carId:id,query:result};}
 else {const r=db.timing?.sessions.find(r=>timingKey(r)===key);if(!r)return;timingDetail={record:structuredClone(r),carId};}
 timingLapPage=0;showTimingSession();
}
async function changeLapPage(direction){
 const next=Math.max(0,timingLapPage+direction),detail=timingDetail;
 if(detail.query){const s=detail.record.payload,result=await api('query','session',{sourceId:s.source.id,sessionId:s.sessionId,carId:detail.carId,offset:next*100,token:detail.query.token});if(timingDetail!==detail)return;timingDetail={...detail,record:result.record,query:result};}
 timingLapPage=next;showTimingSession();
}
function showTimingSession(){
  if(timingDetail.record.format==='history-v1'){modal('Shared racing history', '<p class="note">Expanded session details require the coordinated history update. The original evidence remains stored unchanged.</p>',null);return;}
  const {record:r,carId:id}=timingDetail,s=r.payload,p=s.state==='active'?s.participants.find(p=>p.carId===id):null;
  const audit=`<details class="mt"><summary>Delivery and revision history</summary>${dl([['Timing installation',s.source.name],['Source ID',s.source.id],['Session ID',s.sessionId],['Current revision',s.revision],['Received',connectionTime(r.receivedAt)],['Content hash',r.contentHash]])}<p class="tiny muted">${r.history.length?r.history.map(h=>`Revision ${h.revision}: ${esc(h.state)} · ${esc(connectionTime(h.receivedAt))}`).join('<br>'):'First accepted delivery.'}</p></details>`;
  if(!p){modal('Timing session · '+r.lastName,`<div class="timing-session-details"><p class="note">${esc(s.state==='withdrawn'?s.reason:id?'Car removed by correction.':'No physical car contribution is selected for this session.')} No contribution to this car’s statistics.</p>${audit}</div>`,null);return;}
  const laps=[...p.laps].sort((a,b)=>a.endedAtMs-b.endedAtMs),lapCount=timingDetail.query?.total??laps.length,page=timingDetail.query?laps:laps.slice(timingLapPage*100,timingLapPage*100+100);
  const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const standings=table(['Participant','Position','Status','Classified laps','Classified time','Points'],s.standings.map(row=>[s.participants.find(p=>p.id===row.participantId).displayName,row.position??'—',row.status,row.classifiedLaps,timingSeconds(row.classifiedElapsedMs),row.points]));
  const configuration=`<details class="mt"><summary>Configuration actually raced</summary><p class="tiny muted">Captured ${esc(connectionTime(p.configuration.capturedAt))}; car revision ${p.configuration.carRevision}. Changes made to the current car do not rewrite this snapshot.</p>${dl(Object.entries(p.configuration.technical).map(([k,v])=>[techLabels[k]||k,v]))}${p.configuration.components.length?table(['Installed part','Quantity','Position'],p.configuration.components.map(c=>[c.name,c.quantity,c.position])):''}</details>`;
  const drivers=table(['Heat','Driver','Lane','Start offset','End offset'],p.stints.map(st=>[s.heats.find(h=>h.id===st.heatId).name,p.drivers.find(d=>d.id===st.driverId).name,st.lane,timingSeconds(st.startedAtMs),timingSeconds(st.endedAtMs)]));
  const lapTable=table(['Lap','Heat / driver / lane','Measured','Validity','Record eligible','Distance'],page.map(l=>{const st=p.stints.find(st=>st.id===l.stintId);return [l.number,s.heats.find(h=>h.id===st.heatId).name+' / '+p.drivers.find(d=>d.id===st.driverId).name+' / '+st.lane,timingSeconds(l.durationMs),(l.valid?'Valid':'Invalid')+(l.pit?' · Pit':'')+(l.reason?' · '+l.reason:''),l.recordEligible?'Yes':'No',l.countsForDistance?(l.distanceM===null?'Unknown':l.distanceM+' m'):'Not counted'];}));
  modal('Timing session · '+s.name,`<div class="timing-session-details">${(r._query?.requiresCorrection??TimingResultsModel.requiresCorrection(s))?timingCorrectionNotice():''}<p>${esc(s.track.name)} · ${date(s.startedAt)} · ${badge('Revision '+s.revision)}</p>${timingStatistics(r._query?.summaries.find(x=>x.participantId===p.id)?.statistics||TimingResultsModel.statistics(s,p))}<details class="mt"><summary>Final classification and adjustments</summary><p class="tiny muted">Timing’s reviewed classification is independent of measured lap records. Adjustments shown below are already included in the classification.</p>${standings}${s.adjustments.length?table(['Participant','Adjustment','Amount','Reason'],s.adjustments.map(a=>[s.participants.find(p=>p.id===a.participantId).displayName,a.kind,a.amount,a.reason])):'<p>No adjustments.</p>'}</details>${configuration}<details class="mt"><summary>Heats and driver changes</summary>${drivers}</details><h3 class="mt">Measured laps</h3><p class="tiny muted">${lapCount} laps · page ${timingLapPage+1} of ${Math.max(1,Math.ceil(lapCount/100))}. Pit and invalid laps never set records.</p>${lapTable}<div class="actions mt">${timingLapPage?btn('Previous laps','timing-laps-prev'):''}${(timingLapPage+1)*100<lapCount?btn('Next laps','timing-laps-next'):''}</div><p class="prewrap mt">${esc(s.notes)}</p>${audit}</div>`,null);
}
